export const TOAST_DURATION_MS = 3000;

export const TYPE_MAP: Record<string, string> = {
  'A': '函数与图像',
  'B': '平面几何',
  'C': '解析几何',
  'D': '立体几何',
};

export function formatGenerationTitle(title: string | null, problemType: string | null): string {
  return title || TYPE_MAP[problemType || ''] || '未命名课件';
}
